-- PREPARED ONLY: Z-01..Z-08 connected Web/Desktop assistance and innovation evidence workspace.
-- Not applied. Existing QM, client, task, tour, contact, consent, release and audit originals are read only.
-- Runtime gates still required: PostgreSQL/PostgREST/RLS/grants, two sessions, lock/rollback,
-- legacy/native writers, provider sandboxes, browser/layout and qualified care/design/privacy/legal acceptance.
begin;
create schema if not exists innovation_evidence_private;
revoke all on schema innovation_evidence_private from public,anon,authenticated;
create table if not exists innovation_evidence_private.roots(tenant_id uuid primary key,head_id uuid,updated_at timestamptz not null default clock_timestamp());
create table if not exists innovation_evidence_private.events(id uuid primary key,tenant_id uuid not null,sequence bigint not null,previous_id uuid,request_id uuid not null,actor_id uuid not null,actor_name text not null,occurred_at timestamptz not null,recorded_at timestamptz not null default clock_timestamp(),kind text not null,command jsonb not null,unique(tenant_id,sequence),unique(tenant_id,request_id));
alter table innovation_evidence_private.roots enable row level security;alter table innovation_evidence_private.events enable row level security;
revoke all on all tables in schema innovation_evidence_private from public,anon,authenticated;
create or replace function innovation_evidence_private.immutable()returns trigger language plpgsql security definer set search_path='' as $$begin raise exception using errcode='P0P01',message='Assistenz- und Innovationsverlauf bleibt unveränderlich.';end$$;
drop trigger if exists innovation_evidence_roots_delete on innovation_evidence_private.roots;create trigger innovation_evidence_roots_delete before delete on innovation_evidence_private.roots for each row execute function innovation_evidence_private.immutable();
drop trigger if exists innovation_evidence_events_immutable on innovation_evidence_private.events;create trigger innovation_evidence_events_immutable before update or delete on innovation_evidence_private.events for each row execute function innovation_evidence_private.immutable();

create or replace function innovation_evidence_private.profile_has(t uuid,a uuid,keys text[])returns boolean language sql stable set search_path='' as $$
select exists(select 1 from public.profiles p join public.roles r on r.id=p.role_id where p.id=a and p.tenant_id=t and p.is_active and p.status='active'and not exists(select 1 from unnest(keys)k where not case when exists(select 1 from public.role_permission_sets z where z.tenant_id=t and z.role_key=r.key)then exists(select 1 from public.role_permission_sets z where z.tenant_id=t and z.role_key=r.key and z.permission_key=k)else exists(select 1 from public.role_permissions z where z.role_id=r.id and z.permission_key=k)end))$$;
create or replace function innovation_evidence_private.kind_right(k text)returns text language sql immutable set search_path='' as $$select case
 when k in('voice_capture','documentation_source_set','documentation_draft','contradiction_finding','task_bundle_candidate','tour_candidate','progress_summary','relative_information_scope','innovation_experiment','correction')then'qm.use_ai_assistant'
 when k='voice_transcript_review'then'qm.edit_document'
 when k in('professional_document_review','relative_information_review')then'qm.approve_document'
 when k in('contradiction_resolution','summary_review')then'qm.manage_compliance'
 when k='task_bundle_review'then'qm.create_measure'
 when k in('tour_review','innovation_release_decision')then'qm.manage_settings'end$$;
create or replace function innovation_evidence_private.extra_rights(k text)returns text[] language sql immutable set search_path='' as $$select case
 when k='innovation_release_decision'then array['qm.use_ai_assistant','qm.approve_document']::text[]
 when k in('voice_transcript_review','professional_document_review','contradiction_resolution','task_bundle_review','tour_review','summary_review','relative_information_review')then array['qm.use_ai_assistant']::text[]
 else array[]::text[]end$$;
create or replace function innovation_evidence_private.actor(t uuid,a uuid,k text default null)returns text language plpgsql security definer set search_path='' as $$
declare sid uuid;n text;permission text;required text[]:=array['qm.view','qm.use_ai_assistant'];begin
 if auth.uid()is null or auth.uid()is distinct from a or public.resolve_current_profile_id()is distinct from a or public.current_tenant_id()is distinct from t or coalesce((auth.jwt()->>'exp')::bigint,0)<=extract(epoch from clock_timestamp())then raise exception using errcode='42501',message='Aktuelles eigenes Konto fehlt.';end if;
 sid:=nullif(auth.jwt()->>'session_id','')::uuid;perform 1 from auth.sessions s where s.id=sid and s.user_id=auth.uid()and(s.not_after is null or s.not_after>clock_timestamp())for share;if not found then raise exception using errcode='42501',message='Aktuelle native Sitzung fehlt.';end if;
 permission:=innovation_evidence_private.kind_right(k);if k is not null and permission is null then raise exception using errcode='22023',message='Assistenz- und Innovationsvorgang ist unbekannt.';end if;if permission is not null then required:=required||permission||innovation_evidence_private.extra_rights(k);lock table public.roles,public.role_permissions,public.role_permission_sets in share mode;end if;
 select coalesce(nullif(btrim(p.display_name),''),'Name nicht bestätigt')into n from public.profiles p join public.roles r on r.id=p.role_id where p.id=a and p.tenant_id=t and p.is_active and p.status='active'and(p.auth_user_id is null or p.auth_user_id=auth.uid())for share of p,r;
 if n is null or not innovation_evidence_private.profile_has(t,a,required)then raise exception using errcode='42501',message='Aktuelle QM- oder Assistenzrechte fehlen.';end if;foreach permission in array required loop if public.has_permission(permission)is not true then raise exception using errcode='42501',message='Nativer Rechtezugang fehlt.';end if;end loop;return n;
end$$;

create or replace function innovation_evidence_private.sources(t uuid)returns jsonb language sql security definer set search_path='' as $$with s as(
 select'ai_draft'::text kind,x.id,to_jsonb(x)snapshot from public.qm_ai_drafts x where x.tenant_id=t
 union all select'qm_document',x.id,to_jsonb(x)from public.qm_documents x where x.tenant_id=t
 union all select'qm_document_version',x.id,to_jsonb(x)from public.qm_document_versions x where x.tenant_id=t
 union all select'client_document',x.id,to_jsonb(x)from public.client_documents x where x.tenant_id=t
 union all select'care_plan',x.id,to_jsonb(x)from public.care_plans x where x.tenant_id=t
 union all select'client_task',x.id,to_jsonb(x)from public.client_tasks x where x.tenant_id=t
 union all select'qm_change_task',x.id,to_jsonb(x)from public.qm_change_tasks x where x.tenant_id=t
 union all select'care_tour',x.id,to_jsonb(x)from public.care_tours x where x.tenant_id=t
 union all select'assist_visit',x.id,to_jsonb(x)from public.assist_visits x where x.tenant_id=t
 union all select'client_contact',x.id,to_jsonb(x)from public.client_contacts x where x.tenant_id=t
 union all select'client_consent',x.id,to_jsonb(x)from public.client_consents x where x.tenant_id=t
 union all select'communication_thread',x.id,to_jsonb(x)from public.communication_threads x where x.tenant_id=t
 union all select'release_package',x.id,to_jsonb(x)from public.release_packages x where x.tenant_id=t
 union all select'operations_audit',x.id,to_jsonb(x)from public.operations_audit_events x where x.tenant_id=t
)select coalesce(jsonb_agg(jsonb_build_object('kind',kind,'id',id,'snapshot',snapshot)order by kind,id),'[]'::jsonb)from s$$;

create or replace function innovation_evidence_private.source_rules(k text)returns jsonb language sql immutable set search_path='' as $$select case k
 when'voice_capture'then'{"consent":["client_consent"],"document":["client_document","qm_document"]}'
 when'voice_transcript_review'then'{"draft":["ai_draft"],"document":["client_document","qm_document"]}'
 when'documentation_source_set'then'{"document":["client_document","qm_document"],"version":["qm_document_version"],"plan":["care_plan"]}'
 when'documentation_draft'then'{"draft":["ai_draft"],"version":["qm_document_version"]}'
 when'professional_document_review'then'{"draft":["ai_draft"],"version":["qm_document_version"]}'
 when'contradiction_finding'then'{"left":["client_document","qm_document_version","care_plan"],"right":["client_document","qm_document_version","care_plan"]}'
 when'contradiction_resolution'then'{"finding":["operations_audit"],"followUp":["client_task","qm_change_task"]}'
 when'task_bundle_candidate'then'{"task":["client_task","qm_change_task"],"visit":["assist_visit","care_tour"]}'
 when'task_bundle_review'then'{"task":["client_task","qm_change_task"],"audit":["operations_audit"]}'
 when'tour_candidate'then'{"tour":["care_tour"],"visit":["assist_visit"]}'
 when'tour_review'then'{"tour":["care_tour"],"audit":["operations_audit"]}'
 when'progress_summary'then'{"document":["client_document","qm_document"],"task":["client_task","qm_change_task"],"plan":["care_plan"]}'
 when'summary_review'then'{"document":["client_document","qm_document"],"audit":["operations_audit"]}'
 when'relative_information_scope'then'{"contact":["client_contact"],"consent":["client_consent"],"document":["client_document","qm_document"]}'
 when'relative_information_review'then'{"contact":["client_contact"],"consent":["client_consent"],"thread":["communication_thread"]}'
 when'innovation_experiment'then'{"release":["release_package"],"audit":["operations_audit"]}'
 when'innovation_release_decision'then'{"release":["release_package"],"audit":["operations_audit"]}'
 when'correction'then'{}'end::jsonb$$;
create or replace function innovation_evidence_private.field_keys(k text)returns text[] language sql immutable set search_path='' as $$select case k
 when'voice_capture'then array['audioSha256','language','captureState']when'voice_transcript_review'then array['transcriptSha256','speakerMapSha256','decision']
 when'documentation_source_set'then array['sourceSetSha256','scope']when'documentation_draft'then array['modelId','promptSha256','outputSha256','state']when'professional_document_review'then array['decision','finding','reviewSha256']
 when'contradiction_finding'then array['ruleSet','warningSha256','state']when'contradiction_resolution'then array['decision','rationale','resolutionSha256']
 when'task_bundle_candidate'then array['bundleSha256','constraintSha256','state']when'task_bundle_review'then array['decision','reviewSha256','limitations']
 when'tour_candidate'then array['proposalSha256','constraintSha256','state']when'tour_review'then array['decision','reviewSha256','reason']
 when'progress_summary'then array['summarySha256','coverageSha256','state']when'summary_review'then array['decision','gaps','reviewSha256']
 when'relative_information_scope'then array['scopeSha256','purpose','state']when'relative_information_review'then array['decision','previewSha256','limitations']
 when'innovation_experiment'then array['protocolVersion','baselineSha256','candidateSha256','analysisSha256','benefitState']when'innovation_release_decision'then array['decision','decisionSha256','limitations']
 when'correction'then array['targetId','reason','evidenceSha256']end$$;

create or replace function innovation_evidence_private.validate_command(cmd jsonb,src jsonb)returns void language plpgsql set search_path='' as $$declare k text:=cmd->>'kind';p jsonb:=cmd->'payload';rules jsonb:=innovation_evidence_private.source_rules(k);actual text[];expected text[];entry record;v jsonb;begin
select array_agg(x order by x)into actual from jsonb_object_keys(cmd)x;if jsonb_typeof(cmd)is distinct from'object'or actual is distinct from array['actorId','eventId','expectedHeadId','kind','note','occurredAt','payload','requestId','tenantId','version']::text[]or cmd->>'version'<>'2026-10-16.2'or innovation_evidence_private.kind_right(k)is null or cmd->>'requestId'!~'^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'or cmd->>'eventId'!~'^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'or cmd->>'tenantId'!~'^[0-9a-f-]{36}$'or cmd->>'actorId'!~'^[0-9a-f-]{36}$'or(cmd->'expectedHeadId'<>'null'::jsonb and cmd->>'expectedHeadId'!~'^[0-9a-f-]{36}$')or cmd->>'occurredAt'!~'^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}(\.[0-9]{1,6})?(Z|[+-][0-9]{2}:[0-9]{2})$'or nullif(btrim(cmd->>'note'),'')is null or length(cmd->>'note')>4000 or jsonb_typeof(p)is distinct from'object'or rules is null then raise exception using errcode='22023',message='Assistenz- und Innovationsanfrage ist unvollständig.';end if;
 select array_agg(key order by key)into expected from(select jsonb_object_keys(rules)key union all select unnest(innovation_evidence_private.field_keys(k)))q;select array_agg(x order by x)into actual from jsonb_object_keys(p)x;if actual is distinct from expected then raise exception using errcode='22023',message='Vorgangsfelder sind unvollständig oder enthalten Fremdfelder.';end if;
 for entry in select key,value from jsonb_each(rules)loop v:=p->entry.key;if jsonb_typeof(v)is distinct from'object'or(select array_agg(x order by x)from jsonb_object_keys(v)x)is distinct from array['id','kind','snapshot']::text[]or not exists(select 1 from jsonb_array_elements(entry.value)x where x#>>'{}'=v->>'kind')or v->>'id'!~'^[0-9a-f-]{36}$'or jsonb_typeof(v->'snapshot')is distinct from'object'or v#>>'{snapshot,id}'is distinct from v->>'id'or not exists(select 1 from jsonb_array_elements(src)x where x=v)then raise exception using errcode='40001',message='Originalquelle ist falsch, geändert oder nicht mehr zugänglich.';end if;end loop;
 if(select count(distinct p->key#>>'{snapshot,client_id}')from jsonb_object_keys(rules)key where nullif(p->key#>>'{snapshot,client_id}','')is not null)>1 then raise exception using errcode='23514',message='Originalquellen gehören nicht zum selben Pflegefall.';end if;
 if k='contradiction_finding'and p#>>'{left,id}'=p#>>'{right,id}'then raise exception using errcode='23514',message='Ein Widerspruch benötigt zwei verschiedene Originale.';end if;
 for entry in select x key from unnest(innovation_evidence_private.field_keys(k))x loop if nullif(btrim(p->>entry.key),'')is null then raise exception using errcode='22023',message='Pflichtangabe fehlt.';end if;if entry.key~'(Sha256)$'and(p->>entry.key)!~'^[0-9a-f]{64}$'then raise exception using errcode='22023',message='Fingerabdruck ist ungültig.';elsif entry.key in('createdAt','observedAt','requestedAt','verifiedAt','startedAt','completedAt','resumedAt')and(p->>entry.key)!~'^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}(\.[0-9]{1,6})?(Z|[+-][0-9]{2}:[0-9]{2})$'then raise exception using errcode='22007',message='Zeitpunkt ist ungültig.';elsif entry.key in('targetId','requestId','checkpointId')and(p->>entry.key)!~'^[0-9a-f-]{36}$'then raise exception using errcode='22P02',message='UUID ist ungültig.';end if;end loop;
end$$;

create or replace function innovation_evidence_private.event_json(e innovation_evidence_private.events)returns jsonb language sql immutable set search_path='' as $$select jsonb_build_object('id',e.id,'sequence',e.sequence,'previousId',e.previous_id,'tenantId',e.tenant_id,'actorId',e.actor_id,'actorName',e.actor_name,'recordedAt',to_char(e.recorded_at at time zone'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),'command',e.command)$$;
create or replace function innovation_evidence_private.history(t uuid)returns jsonb language plpgsql security definer set search_path='' as $$declare e innovation_evidence_private.events%rowtype;head uuid;prev uuid;n bigint:=0;rows jsonb:='[]';begin select r.head_id into head from innovation_evidence_private.roots r where r.tenant_id=t;for e in select*from innovation_evidence_private.events z where z.tenant_id=t order by z.sequence loop if e.sequence<>n+1 or e.previous_id is distinct from prev or e.command->>'eventId'is distinct from e.id::text or e.command->>'tenantId'is distinct from t::text or e.command->>'actorId'is distinct from e.actor_id::text or(e.command->>'expectedHeadId')is distinct from prev::text then raise exception using errcode='23514',message='Assistenz- und Innovationsverlauf ist widersprüchlich.';end if;rows:=rows||jsonb_build_array(innovation_evidence_private.event_json(e));prev:=e.id;n:=n+1;end loop;if head is distinct from prev then raise exception using errcode='23514',message='Assistenz- und Innovationsverlaufskopf ist unvollständig.';end if;return jsonb_build_object('version','2026-10-16.2','tenantId',t,'count',n,'headId',head,'events',rows);end$$;
create or replace function innovation_evidence_private.read_context(t uuid,a uuid)returns jsonb language plpgsql security definer set search_path='' as $$declare n text;src jsonb;begin n:=innovation_evidence_private.actor(t,a,null);src:=innovation_evidence_private.sources(t);return jsonb_build_object('version','2026-10-16.2','tenantId',t,'actorId',a,'loadedAt',to_char(clock_timestamp()at time zone'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),'sources',jsonb_build_object('count',jsonb_array_length(src),'rows',src),'history',innovation_evidence_private.history(t));end$$;
create or replace function innovation_evidence_private.commit_event(cmd jsonb)returns jsonb language plpgsql security definer set search_path='' as $$declare t uuid:=(cmd->>'tenantId')::uuid;a uuid:=(cmd->>'actorId')::uuid;rid uuid:=(cmd->>'requestId')::uuid;eid uuid:=(cmd->>'eventId')::uuid;n text;root innovation_evidence_private.roots%rowtype;e innovation_evidence_private.events%rowtype;src jsonb;begin n:=innovation_evidence_private.actor(t,a,cmd->>'kind');perform pg_advisory_xact_lock(hashtextextended('innovation-evidence:'||t::text,0));insert into innovation_evidence_private.roots(tenant_id)values(t)on conflict do nothing;select*into root from innovation_evidence_private.roots r where r.tenant_id=t for update;select*into e from innovation_evidence_private.events z where z.tenant_id=t and z.request_id=rid;if e.id is not null then if e.command is distinct from cmd then raise exception using errcode='23505',message='Anfragekennung gehört zu anderem Inhalt.';end if;return jsonb_build_object('version','2026-10-16.2','requestId',rid,'command',e.command,'event',innovation_evidence_private.event_json(e));end if;src:=innovation_evidence_private.sources(t);perform innovation_evidence_private.validate_command(cmd,src);if(cmd->>'expectedHeadId')is distinct from root.head_id::text then raise exception using errcode='40001',message='Assistenz- und Innovationsverlauf wurde geändert.';end if;if cmd->>'kind'='correction'and not exists(select 1 from innovation_evidence_private.events x where x.tenant_id=t and x.id=(cmd#>>'{payload,targetId}')::uuid and x.kind<>'correction'and not exists(select 1 from innovation_evidence_private.events z where z.tenant_id=t and z.kind='correction'and z.command#>>'{payload,targetId}'=x.id::text))then raise exception using errcode='23514',message='Nur ein vorhandenes unberichtigtes Original kann berichtigt werden.';end if;insert into innovation_evidence_private.events(id,tenant_id,sequence,previous_id,request_id,actor_id,actor_name,occurred_at,kind,command)values(eid,t,coalesce((select max(sequence)+1 from innovation_evidence_private.events where tenant_id=t),1),root.head_id,rid,a,n,(cmd->>'occurredAt')::timestamptz,cmd->>'kind',cmd)returning*into e;update innovation_evidence_private.roots set head_id=eid,updated_at=clock_timestamp()where tenant_id=t;return jsonb_build_object('version','2026-10-16.2','requestId',rid,'command',cmd,'event',innovation_evidence_private.event_json(e));end$$;
create or replace function innovation_evidence_private.confirm_event(t uuid,a uuid,rid uuid,cmd jsonb)returns jsonb language plpgsql security definer set search_path='' as $$declare e innovation_evidence_private.events%rowtype;begin perform innovation_evidence_private.actor(t,a,null);select*into e from innovation_evidence_private.events z where z.tenant_id=t and z.request_id=rid;if e.id is null or e.command is distinct from cmd or e.actor_id<>a then raise exception using errcode='P0P01',message='Passende native Quittung fehlt.';end if;return jsonb_build_object('version','2026-10-16.2','requestId',rid,'command',e.command,'event',innovation_evidence_private.event_json(e));end$$;
create or replace function public.web_innovation_evidence_workspace_context(p_tenant_id uuid,p_actor_id uuid)returns jsonb language sql security invoker set search_path='' as $$select innovation_evidence_private.read_context(p_tenant_id,p_actor_id)$$;
create or replace function public.web_commit_innovation_evidence_event(p_command jsonb)returns jsonb language sql security invoker set search_path='' as $$select innovation_evidence_private.commit_event(p_command)$$;
create or replace function public.web_confirm_innovation_evidence_event(p_tenant_id uuid,p_actor_id uuid,p_request_id uuid,p_command jsonb)returns jsonb language sql security invoker set search_path='' as $$select innovation_evidence_private.confirm_event(p_tenant_id,p_actor_id,p_request_id,p_command)$$;
revoke all on function public.web_innovation_evidence_workspace_context(uuid,uuid),public.web_commit_innovation_evidence_event(jsonb),public.web_confirm_innovation_evidence_event(uuid,uuid,uuid,jsonb)from public,anon;
grant usage on schema innovation_evidence_private to authenticated;
grant execute on function innovation_evidence_private.read_context(uuid,uuid),innovation_evidence_private.commit_event(jsonb),innovation_evidence_private.confirm_event(uuid,uuid,uuid,jsonb)to authenticated;
grant execute on function public.web_innovation_evidence_workspace_context(uuid,uuid),public.web_commit_innovation_evidence_event(jsonb),public.web_confirm_innovation_evidence_event(uuid,uuid,uuid,jsonb)to authenticated;
commit;
